INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('9a64d6c7-0139-4f69-9271-c6030e584e25', '曉濟膠川南入密界', '晓济胶川南入密界', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '飲馬膠川上，傍膠南趣密。\\n林遙飛鳥遲，雲去晴山出。\\n落暉隱桑柘，秋原被花實。\\n慘然遊子寒，風露將蕭瑟。', '诗', 'shi', '', '曉濟膠川南入密界 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('47ed0d19-9151-4877-824a-e71f85229c83', '夜發三泉即事', '夜发三泉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '暗發三泉山，窮秋聽騷屑。\\n北林夜鳴雨，南望曉成雪。\\n祗詠北風涼，詎知南土熱。\\n沙溪忽沸渭，石道乍明滅。\\n宛若銀磧橫，復如瑤臺結。\\n指程賦所戀，遇虞不遑歇。\\n重纊濡莫解，懸旌凍猶揭。\\n下奔泥棧榰，上覯雲梯設。\\n[搏]頰羸馬頓，回眸惴人跌。\\n憧憧往復還，心注思逾切。\\n冉冉年將病，力困衰怠竭。\\n天彭信方隅，地勢誠斗絕。\\n忝曳尚書履，叨兼使臣節。\\n京坻有歲饒，亭障無邊孽。\\n歸奏丹墀左，騫能俟來哲。', '诗', 'shi', '', '夜發三泉即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('caf2f7b9-372f-43f1-bbd1-3faabd0069b5', '小園納涼即事', '小园纳凉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '煩暑避蒸鬱，居閑習高明。\\n長風自遠來，層閣有餘清。\\n散灑納涼氣，蕭條遺世情。\\n奈何誇大隱，終日繫塵纓。', '诗', 'shi', '', '小園納涼即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('a01e17f1-6dbc-4b4e-b859-ed698cdaf86c', '昆明池晏坐答王兵部珣三韻見示', '昆明池晏坐答王兵部珣三韵见示', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '畫舸疾如飛，遙遙汎夕暉。\\n石黥吹浪隱，玉女步塵歸。\\n獨有銜恩處，明珠在釣磯。', '诗', 'shi', '', '昆明池晏坐答王兵部珣三韻見示 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('d0e50379-1882-4fd1-9e61-9b63d0528b67', '題壽安王主簿池館', '题寿安王主簿池馆', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '洛邑通馳道，韓郊在屬城。\\n館將花雨映，潭與竹聲清。\\n賢俊鸞棲棘，賓遊馬佩衡。\\n願言隨狎鳥，從此濯吾纓。', '诗', 'shi', '', '題壽安王主簿池館 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('d69ab328-4934-4278-a54a-4a8169a6aef5', '扈從溫泉奉和姚令公喜雪', '扈从温泉奉和姚令公喜雪', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '清道豐人望，乘時漢主遊。\\n恩暉隨霰下，慶澤與雲浮。\\n泉暖驚銀磧，花寒愛玉樓。\\n鼎臣今有問，河伯且應留。', '诗', 'shi', '', '扈從溫泉奉和姚令公喜雪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('d1ed9973-1f11-4384-a1d3-41a5006446d6', '奉和聖製春臺望應制', '奉和圣制春台望应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '壯麗天之府，神明王者宅。\\n大君乘飛龍，登彼復懷昔。\\n圓闕朱光燄，橫山翠微積。\\n河汧流作表，縣聚開成陌。\\n即舊在皇家，維新具物華。\\n雲連所上居恆屬，日更時中望不斜。\\n三月滄池搖積水，萬年青樹綴新花。\\n暴嬴國此嘗圖霸，霸業後仁先以詐。\\n東破諸侯西入秦，咸陽北阪南渭津。\\n詩書焚爇散學士，高閣奢踰嬌美人。\\n事往覆輈經遠喻，春還按蹕憑高賦。\\n戎觀愛力深惟省，越厭陳方何足務。\\n清吹遙遙發帝臺，宸文耿耿照天迴。\\n伯夷位事愚臣忝，喜奏聲成鳳鳥來。', '诗', 'shi', '', '奉和聖製春臺望應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('1d89959e-48bf-48d4-a3c9-a945fb524c33', '長相思', '长相思', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '君不見天津橋下東流水，南望龍門北朝市。\\n楊柳青青宛地垂，桃紅李白花參差。\\n花參差，柳堪結，此時憶君心斷絕。', '诗', 'shi', '', '長相思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('f15dddef-ce75-47cd-a516-a3058101d894', '蜀城哭台州樂安少府', '蜀城哭台州乐安少府', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '遠遊躋劒閣，長想屬天台。\\n萬里隔三載，此邦余重來。\\n音容曠不覩，夢寐殊悠哉。\\n邊郡饒藉藉，晚庭正回回。\\n喜傳上都封，因促傍吏開。\\n向悟海鹽客，已而梁木摧。\\n變衣寢門外，揮涕少城隈。\\n却記分明得，猶持委曲猜。\\n師儒昔訓獎，仲季時童孩。\\n服義題書篋，邀歡汎酒杯。\\n蹔令風雨散，仍迫歲時迴。\\n其道惟正直，其人信美偲。\\n白頭還作尉，黃綬固非才。\\n可歎懸蛇疾，先貽問鵩災。\\n故鄉閉窮壤，宿草生寒荄。\\n零落九原去，蹉跎四序催。\\n曩期冬贈橘，今哭夏成梅。\\n執禮誰爲賵，居常不徇財。\\n北登嵔𡻱坂，東望姑蘇臺。\\n天路本懸絕，江波復泝洄。\\n念孤心易斷，追往恨艱裁。\\n不遂卿將伯，孰云陳與雷。\\n吾衰亦如此，夫子復何哀。', '诗', 'shi', '', '蜀城哭台州樂安少府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('6f528586-3940-4d2a-8145-474ef8202668', '立春日侍宴內出剪綵花應制', '立春日侍宴内出剪彩花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '曉入宜春苑，穠芳吐禁中。\\n剪刀因裂素，妝粉爲開紅。\\n彩異驚流雪，香饒點便風。\\n裁成識天意，萬物與花同。', '诗', 'shi', '', '立春日侍宴內出剪綵花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('0be48092-4737-4052-a441-cf232f41af7e', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '御道紅旗出，芳園翠輦遊。\\n繞花開水殿，架竹起山樓。\\n荷芰輕薰幄，魚龍出負舟。\\n寧知穆天子，空賦白雲秋。', '诗', 'shi', '', '春日芙蓉園侍宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('159307b8-e963-4996-8162-ab4653a298b3', '奉和聖製人日清暉閣宴羣臣遇雪應制', '奉和圣制人日清晖阁宴群臣遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '樓觀空煙裏，初年瑞雪過。\\n苑花齊玉樹，池水作銀河。\\n七日祥圖啓，千春御賞多。\\n輕飛傳綵勝，天上奉薰歌。', '诗', 'shi', '', '奉和聖製人日清暉閣宴羣臣遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('7df81720-68ee-4257-9536-d0685cce5e26', '奉和七夕宴兩儀殿應制', '奉和七夕宴两仪殿应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '靈媛乘秋發，仙裝警夜催。\\n月光窺欲渡，河色辨應來。\\n機石天文寫，針樓御賞開。\\n竊觀棲鳥至，疑向鵲橋迴。', '诗', 'shi', '', '奉和七夕宴兩儀殿應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('bc67c445-07f7-4832-b519-86868d613ce3', '奉和九日幸臨渭亭登高應制得時字', '奉和九日幸临渭亭登高应制得时字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '嘉會宜長日，高筵順動時。\\n曉光雲外洗，晴色雨餘滋。\\n降鶴因韶德，吹花入御詞。\\n願陪陽數節，億萬九秋期。', '诗', 'shi', '', '奉和九日幸臨渭亭登高應制得時字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('4ca540c1-3bfa-4b0a-bc27-ac5fd7cde86f', '游禁苑幸臨渭亭遇雪應制', '游禁苑幸临渭亭遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '平明敞帝居，霰雪下凌虛。\\n寫月含珠綴，從風薄綺疏。\\n年驚花絮早，春夜管弦初。\\n已屬雲天外，欣承霈澤餘。', '诗', 'shi', '', '游禁苑幸臨渭亭遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('df411b69-4327-4ab0-81cc-1bdca8b6ad83', '奉和送金城公主適西蕃應制', '奉和送金城公主适西蕃应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '帝女出天津，和戎轉罽輪。\\n川經斷腸望，地與析支鄰。\\n奏曲風嘶馬，銜悲月伴人。\\n旋知偃兵革，長是漢家親。', '诗', 'shi', '', '奉和送金城公主適西蕃應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('b197aa21-a571-49a8-80eb-e01c503a0cfc', '奉和聖製登驪山高頂寓目應制', '奉和圣制登骊山高顶寓目应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '仙蹕御層氛，高高積翠分。\\n巖聲中谷應，天語半空聞。\\n豐樹連黃葉，函關入紫雲。\\n聖圖恢宇縣，歌賦小橫汾。', '诗', 'shi', '', '奉和聖製登驪山高頂寓目應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('431d0b6c-81af-4e69-a83b-6e1c42e56d78', '侍宴桃花園詠桃花應制', '侍宴桃花园咏桃花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '桃花灼灼有光輝，無數成蹊點更飛。\\n爲見芳林含笑待，遂同溫樹不言歸。', '诗', 'shi', '', '侍宴桃花園詠桃花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('102e706b-89de-48c7-9a68-b6a08b25c9b5', '秋社日崇讓園宴得新字', '秋社日崇让园宴得新字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '鳴爵三農稔，勾龍百代神。\\n運昌叨輔弼，時泰喜黎民。\\n樹缺池光近，雲開日影新。\\n生全應有地，長願樂交親。', '诗', 'shi', '', '秋社日崇讓園宴得新字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('3c05330b-1f5e-4b8e-a7b8-bb090ae92808', '奉和魏僕射秋日還鄉有懷之作', '奉和魏仆射秋日还乡有怀之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '南宮夙拜罷，東道晝遊初。\\n飲餞傾冠蓋，傳呼問里閭。\\n樹悲懸劒所，溪想釣璜餘。\\n明發輝光至，增榮駟馬車。', '诗', 'shi', '', '奉和魏僕射秋日還鄉有懷之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('20e40ff6-e0e9-4252-847c-ef59cb447495', '武[擔]山寺', '武[担]山寺', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '武[擔]獨蒼然，墳山下玉泉。\\n鱉靈時共盡，龍女事同遷。\\n松柏銜哀處，幡花種福田。\\n詎知留鏡石，長與法輪圓。', '诗', 'shi', '', '武[擔]山寺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('a38183b4-3508-4ec9-b868-b4ada737a761', '餞潞州陸長史再守汾州', '饯潞州陆长史再守汾州', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '河尹政成期，爲汾昔所推。\\n不榮三入地，還美再臨時。\\n擁傳雲初合，聞鶯日正遲。\\n道傍多出餞，別有吏民思。', '诗', 'shi', '', '餞潞州陸長史再守汾州 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('65b7c4bd-b35c-4f56-81f0-a29f1b427a29', '餞荆州崔司馬', '饯荆州崔司马', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '茂禮雕龍昔，香名展驥初。\\n水連南海漲，星拱北辰居。\\n稍發仙人履，將題別駕輿。\\n明年徵拜入，荆玉不藏諸。', '诗', 'shi', '', '餞荆州崔司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('d24e38e5-b873-42f2-8f43-02ef2d6b61d0', '送吏部李侍郎東歸得歸字', '送吏部李侍郎东归得归字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '陌上有光輝，披雲向洛畿。\\n賞來榮扈從，別至惜分飛。\\n泉溜含風急，山煙帶日微。\\n茂曹今去矣，人物喜東歸。', '诗', 'shi', '', '送吏部李侍郎東歸得歸字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('06b6a208-f048-40c0-9f03-b076f891c028', '送光祿姚卿還都', '送光禄姚卿还都', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '漢室有英台，荀家寵俊才。\\n九卿朝已入，三子暮同來。\\n不授綸爲草，還司鼎用梅。\\n兩京王者宅，駟馬日應迴。', '诗', 'shi', '', '送光祿姚卿還都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('5ae47935-e2df-4070-b7e0-e273ebc48549', '春晚送瑕丘田少府還任因寄洛中鏡上人', '春晚送瑕丘田少府还任因寄洛中镜上人', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '聞道還沂上，因聲寄洛濱。\\n別時花欲盡，歸處酒應春。\\n聚散同行客，悲歡屬故人。\\n少年追樂地，遙贈一霑巾。', '诗', 'shi', '', '春晚送瑕丘田少府還任因寄洛中鏡上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('160135e4-5dc7-46b0-8ec2-ba5430b0e05e', '送賈起居奉使入洛取圖書因便拜覲', '送贾起居奉使入洛取图书因便拜觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '舊國才因地，當朝史命官。\\n遺文徵闕簡，還思采芳蘭。\\n傳發關門候，觴稱邑里歡。\\n早持京副入，旋佇洛書刊。', '诗', 'shi', '', '送賈起居奉使入洛取圖書因便拜覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('ce6d8141-f62a-44e9-a533-0a88f7cce28e', '送常侍舒公歸覲', '送常侍舒公归觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '朝聞講藝餘，晨省拜恩初。\\n訓胄尊庠序，榮親耀里閭。\\n朱丹華轂送，斑白綺筵舒。\\n江上春流滿，還應薦躍魚。', '诗', 'shi', '', '送常侍舒公歸覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('ae418edf-29f6-4110-89d8-add12c322b15', '興州出行', '兴州出行', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '危途曉未分，驅馬傍江濆。\\n滴滴泣花露，微微出岫雲。\\n松梢半吐月，蘿翳漸移曛。\\n旅客腸應斷，吟猿更使聞。', '诗', 'shi', '', '興州出行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('8f752d20-1dce-4bbd-a5fc-0d15970f2c70', '邊秋薄暮', '边秋薄暮', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '海外秋鷹擊，霜前旅雁歸。\\n邊風思鞞鼓，落日慘旌麾。\\n浦暗漁舟入，川長獵騎稀。\\n客悲逢薄暮，況乃事戎機。', '诗', 'shi', '', '邊秋薄暮 shi');